-- 06_Ejecutar_Todas_Las_Pruebas_Grupo06.sql - PROYECTO IQUAL (SGE) - Grupo 6
-- Ejecuta los 104 casos de 06_PruebasSQL.xlsx de una sola vez, en orden.
-- Antes: cargar 03_ModeloSQL_Grupo06, 04_DatosSQL_Grupo06 y 05_Backend_Grupo06.
-- Se corre con el cliente de consola mysql para que todos los resultados queden en un archivo de texto:
--   mysql -u root -pCLAVE --default-character-set=utf8mb4 -t -v --force iqual < 06_Ejecutar_Todas_Las_Pruebas_Grupo06.sql > resultados_pruebas.txt 2>&1
-- sp_aux_recargar_datos es solo para este script: vuelve a cargar los datos de 04 cuando un caso lo pide y se borra al final.

USE iqual;
SET SQL_SAFE_UPDATES = 0;
DROP PROCEDURE IF EXISTS sp_aux_recargar_datos;
DELIMITER //
CREATE PROCEDURE sp_aux_recargar_datos()
BEGIN
    SET FOREIGN_KEY_CHECKS = 0;
    TRUNCATE TABLE log_auditoria;
    TRUNCATE TABLE inscripcion_ed_fisica;
    TRUNCATE TABLE oferta_deporte;
    TRUNCATE TABLE reserva_sector;
    TRUNCATE TABLE prestamo_ct;
    TRUNCATE TABLE recurso_software;
    TRUNCATE TABLE recursos_ct;
    TRUNCATE TABLE donacion_buffet;
    TRUNCATE TABLE detalle_venta;
    TRUNCATE TABLE venta_buffet;
    TRUNCATE TABLE producto_buffet;
    TRUNCATE TABLE integrante_grupo;
    TRUNCATE TABLE grupo_buffet;
    TRUNCATE TABLE reporte_higiene;
    TRUNCATE TABLE consulta_objeto;
    TRUNCATE TABLE reclamo_objeto;
    TRUNCATE TABLE objeto_perdido;
    TRUNCATE TABLE sector;
    TRUNCATE TABLE horario_dia;
    TRUNCATE TABLE horario_escolar;
    TRUNCATE TABLE materia;
    TRUNCATE TABLE usuario;
    TRUNCATE TABLE curso;
    TRUNCATE TABLE franja_horaria;
    TRUNCATE TABLE division;
    TRUNCATE TABLE anio;
    TRUNCATE TABLE software;
    TRUNCATE TABLE categoria_producto;
    TRUNCATE TABLE tipo_sector;
    TRUNCATE TABLE entidad_log;
    TRUNCATE TABLE resultado_log;
    TRUNCATE TABLE tipo_log;
    TRUNCATE TABLE deporte;
    TRUNCATE TABLE carro;
    TRUNCATE TABLE estado_recurso;
    TRUNCATE TABLE tipo_recurso;
    TRUNCATE TABLE estado_venta;
    TRUNCATE TABLE estado_reserva;
    TRUNCATE TABLE estado_reporte;
    TRUNCATE TABLE tipo_reporte;
    TRUNCATE TABLE estado_reclamo;
    TRUNCATE TABLE estado_objeto;
    TRUNCATE TABLE categoria_objeto;
    TRUNCATE TABLE dia_semana;
    TRUNCATE TABLE turno;
    TRUNCATE TABLE especialidad;
    TRUNCATE TABLE rol;
    SET FOREIGN_KEY_CHECKS = 1;
    UPDATE producto_buffet SET id_categoria_producto = (SELECT id_categoria_producto FROM categoria_producto WHERE nombre_categoria = 'Comida') WHERE nombre_producto IN ('Alfajor de dulce de leche', 'Sándwich de miga');
    UPDATE producto_buffet SET id_categoria_producto = (SELECT id_categoria_producto FROM categoria_producto WHERE nombre_categoria = 'Bebida') WHERE nombre_producto = 'Jugo en caja';
END //
DELIMITER ;

CALL sp_aux_recargar_datos();

